<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref} from 'vue'
import {useWorkspace} from '../../app/workspace'
import {createLatestRequests,isCancelled} from '../../shared/api/client'
import {formatTimestamp} from '../../shared/time'
import Pagination from '../../shared/components/Pagination.vue'
import FormDialog from '../../shared/components/FormDialog.vue'
import PersonCaseCandidates from './PersonCaseCandidates.vue'
import PersonRecordEditor from './PersonRecordEditor.vue'
import PersonProfileEditor from './PersonProfileEditor.vue'
import PersonActionDialog from './PersonActionDialog.vue'
import {recordNames,types,verification,states,writePermissions,taskTypes,today,detailLabels,detailValues,eventLabels,type Profile,type PersonRecord,type RecordKind} from './types'
const props=defineProps<{personId:string}>(),emit=defineEmits<{close:[];updated:[]}>()
const {api,command,can,captureSession}=useWorkspace(),requests=createLatestRequests(api)
const person=ref<Profile|null>(null),busy=ref(false),error=ref(''),notice=ref(''),tab=ref('BASE'),actorId=ref(''),records=ref<PersonRecord[]>([]),page=ref(1),total=ref(0),showRecord=ref<PersonRecord|null>(null),editorKind=ref<RecordKind|null>(null),replacing=ref<PersonRecord|null>(null),recordEditing=ref(false),profileEditor=ref(false),reviewing=ref<PersonRecord|null|undefined>(undefined),executing=ref<PersonRecord|null>(null)
type Task={id:string;record_id:string|null;title:string;task_type:string;due_on:string;status:string;result_note:string;version:number;overdue:boolean}
type History={id:string;record_id:string|null;action:string;note:string;actor:string;created_at:string;payload:{document_no?:string;record?:{basis:string;details:Record<string,string>}}|null}
const tasks=ref<Task[]>([]),history=ref<History[]>([]),newTask=ref(false),taskTitle=ref(''),taskDue=ref(today()),taskType=ref('FOLLOWUP'),taskAction=ref<Task|null>(null),taskNote=ref(''),taskResolution=ref('DONE'),transferOpen=ref(false),units=ref<{id:string;name:string}[]>([]),transferTarget=ref(''),transferReason=ref('')
const tabs=computed(()=>[{key:'BASE',name:'基础信息'},...(['USE','CASE','MEASURE','TEST','FOLLOWUP'] as RecordKind[]).filter(kind=>kind==='CASE'?can('cases.read'):can('persons.health')).map(kind=>({key:kind,name:recordNames[kind]})),...(can('persons.health')?[{key:'TASKS',name:'待办事项'}]:[]),...(can('cases.read')&&person.value?.legacy_candidates_visible?[{key:'CANDIDATES',name:'历史候选'}]:[]),{key:'HISTORY',name:'历史记录'}])
const currentKind=computed(()=>['USE','CASE','MEASURE','TEST','FOLLOWUP'].includes(tab.value)?tab.value as RecordKind:null)
const canAdd=computed(()=>!!currentKind.value&&can(writePermissions[currentKind.value])&&person.value?.can_manage)
async function act(task:()=>Promise<void>){busy.value=true;error.value='';try{await task()}catch(e){if(!isCancelled(e))error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function profile(){const result=await requests.latest<Profile>('profile',`/person-drafts/${props.personId}`);person.value=result}
async function load(target=1){if(currentKind.value){const result=await requests.latest<{items:PersonRecord[];total:number}>('records',`/person-drafts/${props.personId}/records?kind=${currentKind.value}&page=${target}`);records.value=result.items;total.value=result.total}else if(tab.value==='TASKS'){const result=await requests.latest<{items:Task[];total:number}>('tasks',`/person-drafts/${props.personId}/tasks?page=${target}`);tasks.value=result.items;total.value=result.total}else if(tab.value==='HISTORY'){const result=await requests.latest<{items:History[];total:number}>('history',`/person-drafts/${props.personId}/history?page=${target}`);history.value=result.items;total.value=result.total}page.value=target;showRecord.value=null}
async function switchTab(key:string){tab.value=key;records.value=[];tasks.value=[];history.value=[];total.value=0;await act(()=>load(1))}
async function saved(){editorKind.value=null;profileEditor.value=false;reviewing.value=undefined;executing.value=null;notice.value='办理结果已记录';await act(async()=>{await profile();await load(page.value)});emit('updated')}
async function createTask(){if(!person.value)return;await act(async()=>{const valid=captureSession();await command('person-task-'+props.personId,`/person-drafts/${props.personId}/tasks`,{person_version:person.value!.version,title:taskTitle.value,due_on:taskDue.value,task_type:taskType.value});if(!valid())return;newTask.value=false;taskTitle.value='';await profile();await load(1);emit('updated')})}
async function completeTask(){if(!taskAction.value)return;await act(async()=>{await command('person-task-close-'+taskAction.value!.id,`/person-drafts/tasks/${taskAction.value!.id}/complete`,{version:taskAction.value!.version,action:taskResolution.value,note:taskNote.value});taskAction.value=null;await profile();await load();emit('updated')})}
async function startTransfer(){await act(async()=>{const options=await requests.latest<{organizations:typeof units.value}>('transfer-options','/person-drafts/transfers/options');units.value=options.organizations;transferOpen.value=true;transferTarget.value='';transferReason.value=''})}
async function transfer(){if(!person.value)return;await act(async()=>{const valid=captureSession();await command('person-transfer-'+props.personId,`/person-drafts/${props.personId}/transfers`,{person_version:person.value!.version,target_org_id:transferTarget.value,reason:transferReason.value});if(!valid())return;transferOpen.value=false;notice.value='移交申请已发起，等待接收单位确认';await profile();emit('updated')})}
onMounted(()=>{void act(async()=>{await profile();actorId.value=(await requests.latest<{actor_id:string}>('options','/person-drafts/options')).actor_id})});onBeforeUnmount(()=>requests.dispose())
</script>
<template><section class="card person-detail"><div class="page-toolbar"><h2>{{person?.name||'人员详情'}}</h2><button class="link" :disabled="busy" @click="emit('close')">关闭档案</button></div><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="success" role="status">{{notice}}</p><p v-if="!person" role="status">正在读取人员档案…</p><template v-if="person"><div class="person-overview"><span class="tag">身份{{verification[person.verification_status]}}</span><span>{{person.document_mask}}</span><span>责任单位：{{person.responsible_org}}</span><span>责任人：{{person.responsible_user||'未指定'}}</span></div><p v-if="person.measure_conflict" class="warning">存在多项待执行或执行中的措施，请核对文书及执行关系；系统未自动决定优先级或结束其中一项。</p><div class="person-tabs" role="tablist" aria-label="人员档案分区"><button v-for="item in tabs" :key="item.key" role="tab" :aria-selected="tab===item.key" :class="{secondary:tab!==item.key}" :disabled="busy" @click="switchTab(item.key)">{{item.name}}</button></div>
<fieldset class="person-fields" :disabled="busy"><div v-if="tab==='BASE'"><dl class="person-facts"><div><dt>名称</dt><dd>{{person.name}}</dd></div><div><dt>来源</dt><dd>{{person.source}}</dd></div><div><dt>身份核验</dt><dd>{{verification[person.verification_status]}}</dd></div><template v-if="person.identity_visible"><div><dt>完整证件 / 身份编号</dt><dd>{{person.document_number||'未填写'}}</dd></div><div><dt>出生日期</dt><dd>{{person.birth_date||'未填写'}}</dd></div><div><dt>联系电话</dt><dd>{{person.phone||'未填写'}}</dd></div><div><dt>联系地址</dt><dd>{{person.address||'未填写'}}</dd></div></template><div><dt>正式案件关系</dt><dd>{{person.case_count===null?'未授权':person.case_count+' 条'}}</dd></div><div><dt>吸毒相关已核验记录</dt><dd>{{person.use_count===null?'未授权':person.use_count+' 条'}}</dd></div><div><dt>当前戒毒措施</dt><dd>{{!person.health_visible?'未授权':person.current_measures.map(row=>types.MEASURE[row.record_type]+' · '+states[row.state]).join('；')||'无已核验的待执行/执行措施'}}</dd></div><div><dt>创建时间</dt><dd>{{formatTimestamp(person.created_at)}}</dd></div></dl><div class="actions"><button v-if="can('persons.write')&&person.can_manage" @click="profileEditor=true;error=''">维护主档</button><button v-if="can('persons.verify')&&can('persons.identity')&&person.can_manage" class="secondary" @click="reviewing=null;error=''">核验身份</button><button v-if="can('persons.transfer')&&person.can_manage" class="secondary" :disabled="person.verification_status!=='VERIFIED'" @click="startTransfer">发起责任移交</button></div><p class="muted person-hint">身份、吸毒事实、案件角色和戒毒措施分别核验。只有明确记录和有效文书才进入相应业务视图，同名不自动合并。</p></div>
<template v-else-if="currentKind"><div class="page-toolbar page-toolbar-actions"><button v-if="canAdd" @click="editorKind=currentKind;replacing=null;recordEditing=false;error=''">登记{{recordNames[currentKind]}}</button></div><div class="table-wrap"><table><thead><tr><th class="row-number">序号</th><th>业务类型</th><th>事实 / 决定日期</th><th>来源</th><th>文书 / 报告编号</th><th>核验状态</th><th>执行状态</th><th>预计结束</th><th>操作</th></tr></thead><tbody><tr v-for="(row,index) in records" :key="row.id"><td class="row-number">{{(page-1)*20+index+1}}</td><td>{{types[row.kind][row.record_type]}}</td><td>{{row.occurred_on}}</td><td>{{row.source}}</td><td>{{row.document_no}}</td><td>{{verification[row.verification_status]}}</td><td>{{states[row.state]}}</td><td>{{row.expected_end_on||'—'}}</td><td><button class="link" @click="showRecord=showRecord?.id===row.id?null:row">详情</button><button v-if="can('persons.verify')&&can(writePermissions[row.kind])&&row.manager_org_id===person.responsible_org_id&&person.can_manage&&!['REVOKED','SUPERSEDED'].includes(row.verification_status)" class="link" @click="reviewing=row;error=''">核验 / 撤销</button><button v-if="row.kind==='MEASURE'&&can('persons.treatment')&&person.can_manage&&row.verification_status==='VERIFIED'&&['DECIDED','ACTIVE'].includes(row.state)" class="link" @click="executing=row;error=''">登记执行</button><button v-if="['PENDING','RETURNED'].includes(row.verification_status)&&person.can_manage&&can(writePermissions[row.kind])" class="link" @click="editorKind=row.kind;replacing=row;recordEditing=true;error=''">补充资料</button><button v-if="row.kind!=='MEASURE'&&row.verification_status==='VERIFIED'&&person.can_manage&&can(writePermissions[row.kind])" class="link" @click="editorKind=row.kind;replacing=row;recordEditing=false;error=''">更正记录</button></td></tr></tbody></table><p v-if="!records.length" class="empty">暂无可查看的{{recordNames[currentKind]}}</p></div><Pagination :page="page" :total="total" :loading="busy" @change="act(()=>load($event))"/><div v-if="showRecord" class="detail"><h3>业务记录详情</h3><p v-if="showRecord.case_id">案件：{{showRecord.case_number}} · {{showRecord.case_title}}</p><p class="person-text">登记依据：{{showRecord.basis}}</p><dl class="person-facts"><div v-for="(value,key) in showRecord.details" :key="key"><dt>{{detailLabels[key]||key}}</dt><dd>{{detailValues[value]||value||'未填写'}}</dd></div></dl><p v-if="showRecord.kind==='MEASURE'">实际开始：{{showRecord.actual_start_on||'未记录'}} · 实际结束：{{showRecord.actual_end_on||'未记录'}}</p></div></template>
<template v-else-if="tab==='TASKS'"><div class="page-toolbar"><p class="muted person-hint">提醒依据来自人工指定日期或已核验记录；完成待办不会自动解除措施。</p><button v-if="can('persons.followup')&&person.can_manage" @click="newTask=true;error=''">新增待办</button></div><div class="table-wrap"><table><thead><tr><th class="row-number">序号</th><th>待办事项</th><th>类型</th><th>日期</th><th>状态</th><th>处理结果</th><th>操作</th></tr></thead><tbody><tr v-for="(row,index) in tasks" :key="row.id"><td class="row-number">{{(page-1)*20+index+1}}</td><td>{{row.title}}</td><td>{{taskTypes[row.task_type]}}</td><td>{{row.due_on}}<span v-if="row.overdue" class="person-overdue"> 逾期</span></td><td>{{({OPEN:'待处理',DONE:'已核对',CANCELLED:'已取消'} as Record<string,string>)[row.status]}}</td><td>{{row.result_note||'—'}}</td><td><button v-if="row.status==='OPEN'&&can('persons.followup')" class="link" @click="taskAction=row;taskNote='';taskResolution='DONE';error=''">处理</button></td></tr></tbody></table><p v-if="!tasks.length" class="empty">暂无待办</p></div><Pagination :page="page" :total="total" @change="act(()=>load($event))"/></template>
<PersonCaseCandidates v-else-if="tab==='CANDIDATES'" :person="person" @close="switchTab('BASE')" @updated="saved"/>
<template v-else-if="tab==='HISTORY'"><div class="table-wrap"><table><thead><tr><th class="row-number">序号</th><th>动作</th><th>办理意见</th><th>操作人</th><th>时间</th></tr></thead><tbody><tr v-for="(entry,index) in history" :key="entry.id"><td class="row-number">{{(page-1)*20+index+1}}</td><td>{{eventLabels[entry.action]||'历史业务动作'}}</td><td class="person-history-note">{{entry.note}}<details v-if="entry.payload&&entry.record_id"><summary>当次业务依据</summary><p class="person-hint">{{entry.payload.document_no||entry.payload.document_no===''?'文书：'+entry.payload.document_no:'见本次登记依据与完整业务记录'}}</p><template v-if="entry.payload.record"><p class="person-text">{{entry.payload.record.basis}}</p><dl class="person-facts"><div v-for="(value,key) in entry.payload.record.details" :key="key"><dt>{{detailLabels[String(key)]||key}}</dt><dd>{{detailValues[String(value)]||value}}</dd></div></dl></template></details></td><td>{{entry.actor}}</td><td>{{formatTimestamp(entry.created_at)}}</td></tr></tbody></table><p v-if="!history.length" class="empty">暂无授权范围内的历史记录</p></div><Pagination :page="page" :total="total" @change="act(()=>load($event))"/></template></fieldset>
<PersonProfileEditor v-if="profileEditor" :person="person" @close="profileEditor=false" @saved="saved"/><PersonRecordEditor v-if="editorKind" :person="person" :kind="editorKind" :replaces="replacing" :editing="recordEditing" @close="editorKind=null" @saved="saved"/><PersonActionDialog v-if="reviewing!==undefined" :person="person" :record="reviewing" mode="review" @close="reviewing=undefined" @saved="saved"/><PersonActionDialog v-if="executing" :person="person" :record="executing" mode="execute" @close="executing=null" @saved="saved"/>
<FormDialog v-if="newTask" title="新增人员待办" :busy="busy" :error="error" @close="newTask=false"><form @submit.prevent="createTask"><label>待办类型<select v-model="taskType"><option v-for="(label,key) in taskTypes" :key="key" :value="key">{{label}}</option></select></label><label>待办标题<input v-model="taskTitle" maxlength="200" required></label><label>办理日期<input v-model="taskDue" type="date" required></label><button :disabled="busy">保存待办</button></form></FormDialog><FormDialog v-if="taskAction" title="核对人员待办" :busy="busy" :error="error" @close="taskAction=null"><form @submit.prevent="completeTask"><p>{{taskAction.title}}</p><label>处理方式<select v-model="taskResolution"><option value="DONE">已核对</option><option value="CANCELLED">取消待办</option></select></label><label>核对结果<textarea v-model="taskNote" maxlength="2000" required></textarea></label><button :disabled="busy">记录处理结果</button></form></FormDialog><FormDialog v-if="transferOpen" title="发起人员责任移交" :busy="busy" :error="error" @close="transferOpen=false"><form @submit.prevent="transfer"><label>接收单位<select v-model="transferTarget" required><option value="" disabled>选择接收单位</option><option v-for="unit in units" :key="unit.id" :value="unit.id">{{unit.name}}</option></select></label><label>移交原因<textarea v-model="transferReason" maxlength="2000" required></textarea></label><p class="muted person-hint">确认接收后移交当前措施和待办的责任，不自动共享原单位全部涉案或检测历史。</p><button :disabled="busy">发起移交申请</button></form></FormDialog>
</template></section></template>
